"use client";
import React,{useState} from "react";import api from "@/lib/api";
import {useResource,Table,Notice,field,button,message} from "@/components/BillingUI";
interface Customer{id:number;name:string;phone:string;notes:string}
export default function Page(){const {data,loading,error,load}=useResource<Customer>("/api/customers");const [edit,setEdit]=useState<Partial<Customer>|null>(null);const [note,setNote]=useState("");const [saving,setSaving]=useState(false);
const save=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);try{if(edit?.id)await api.put(`/api/customers/${edit.id}`,edit);else await api.post("/api/customers",edit);setEdit(null);await load();}catch(e){setNote(message(e));}finally{setSaving(false);}};
return <div className="mx-auto max-w-7xl space-y-6"><div className="flex justify-between"><h1 className="text-2xl font-semibold text-slate-900">Customers</h1><button onClick={()=>setEdit({name:"",phone:"",notes:""})} className={button}>Add customer</button></div><Notice text={error||note}/>{edit&&<form onSubmit={save} className="space-y-4 rounded-xl border border-slate-200 bg-white p-5"><label className="block text-xs text-slate-700">Full name<input required maxLength={120} value={edit.name} onChange={e=>setEdit({...edit,name:e.target.value})} className={field}/></label><label className="block text-xs text-slate-700">Phone<input maxLength={32} value={edit.phone||""} onChange={e=>setEdit({...edit,phone:e.target.value})} className={field}/></label><label className="block text-xs text-slate-700">Notes<textarea maxLength={500} value={edit.notes||""} onChange={e=>setEdit({...edit,notes:e.target.value})} className={field}/></label><div className="flex gap-4"><button disabled={saving} className={button}>Save customer</button><button type="button" onClick={()=>setEdit(null)} className="text-xs text-slate-500">Cancel</button></div></form>}<Table rows={data} loading={loading} columns={[{label:"Customer ID",render:c=>`C${c.id}`},{label:"Full name",render:c=>c.name},{label:"Phone",render:c=>c.phone||"—"},{label:"Notes",render:c=>c.notes||"—"},{label:"Action",render:c=><button onClick={()=>setEdit(c)} className="text-blue-700">Edit</button>}]}/></div>;}
